167|function useDataFetch<T>(url: string, options: { headers?: Record<string, string> } = {}) {
168|  const [data, setData] = React.useState<T | null>(null);
169|  const [isLoading, setIsLoading] = React.useState(Boolean(url));
170|  const [error, setError] = React.useState<string | null>(null);
171|  const [refreshNonce, setRefreshNonce] = React.useState(0);
172|  const headersKey = JSON.stringify(options.headers ?? {});
173|
174|  const refresh = React.useCallback(async () => {
175|    setRefreshNonce((previous) => previous + 1);
176|  }, []);
177|
178|  React.useEffect(() => {
179|    if (!url) {
180|      setData(null);
181|      setIsLoading(false);
182|      setError(null);
183|      return undefined;
184|    }
185|
186|    let cancelled = false;
187|    const load = async () => {
188|      setIsLoading(true);
189|      setError(null);
190|      try {
191|        const response = await designerFetch(url, {
192|          method: "GET",
193|          headers: options.headers,
194|        });
195|        if (!response.ok) {
196|          throw new Error(await parseApiErrorMessage(response));
197|        }
198|        const payload = (await response.json()) as T;
199|        if (!cancelled) {
200|          setData(payload);
201|        }
202|      } catch (loadError) {
203|        if (!cancelled) {
204|          setData(null);
205|          setError(loadError instanceof Error ? loadError.message : "Request failed");
