207|      } finally {
208|        if (!cancelled) {
209|          setIsLoading(false);
210|        }
211|      }
212|    };
213|
214|    void load();
215|    return () => {
216|      cancelled = true;
217|    };
218|  }, [url, headersKey, refreshNonce]);
219|
220|  return { data, isLoading, error, refresh };
