279|const transformApiRowsToChartData = (
280|  rows: Array<Record<string, unknown>>,
281|  mapping: { categoryField: string; categoryAs?: string; series: Array<{ apiField: string; seriesKey: string; aggregation?: string }> },
282|): Array<Record<string, string | number>> => {
283|  const categoryKey = mapping.categoryAs?.trim() || "label";
284|  const parseNum = (raw: unknown): number => {
285|    if (typeof raw === "number" && Number.isFinite(raw)) return raw;
286|    if (typeof raw === "string") { const p = Number(raw); return Number.isFinite(p) ? p : 0; }
287|    return 0;
288|  };
289|  const aggregate = (values: number[], agg: string): number => {
290|    if (values.length === 0) return 0;
291|    if (agg === "count") return values.length;
292|    if (agg === "avg") return values.reduce((s, v) => s + v, 0) / values.length;
293|    if (agg === "min") return Math.min(...values);
294|    if (agg === "max") return Math.max(...values);
295|    if (agg === "sum") return values.reduce((s, v) => s + v, 0);
296|    return values[0] ?? 0;
297|  };
298|  const needsGrouping = mapping.series.some((s) => s.aggregation && s.aggregation !== "none");
299|  if (!needsGrouping) {
300|    return rows.map((row) => {
301|      const chartRow: Record<string, string | number> = { [categoryKey]: String(row[mapping.categoryField] ?? "") };
302|      for (const series of mapping.series) { chartRow[series.seriesKey] = parseNum(row[series.apiField]); }
303|      return chartRow;
304|    });
305|  }
306|  const grouped = new Map<string, Array<Record<string, unknown>>>();
307|  for (const row of rows) {
308|    const cat = String(row[mapping.categoryField] ?? "");
309|    const bucket = grouped.get(cat);
310|    if (bucket) bucket.push(row); else grouped.set(cat, [row]);
311|  }
312|  return Array.from(grouped.entries()).map(([category, groupRows]) => {
313|    const chartRow: Record<string, string | number> = { [categoryKey]: category };
314|    for (const series of mapping.series) {
315|      const values = groupRows.map((r) => parseNum(r[series.apiField]));
316|      chartRow[series.seriesKey] = aggregate(values, series.aggregation ?? "sum");
317|    }
318|    return chartRow;
319|  });
320|};
