335|      id: readVizStringField(row, mapping.idField, `node-${index + 1}`),
336|      label: readVizStringField(row, mapping.labelField, `Item ${index + 1}`),
337|    }));
338|  }
339|  const nodeMap = new Map<string, { id: string; label: string; children: unknown[] }>();
340|  rows.forEach((row, index) => {
341|    const id = readVizStringField(row, mapping.idField, `node-${index + 1}`);
342|    nodeMap.set(id, { id, label: readVizStringField(row, mapping.labelField, id), children: [] });
343|  });
344|  const roots: Array<{ id: string; label: string; children?: unknown[] }> = [];
345|  rows.forEach((row) => {
346|    const id = readVizStringField(row, mapping.idField);
347|    const node = nodeMap.get(id);
348|    if (!node) return;
349|    const parentId = readVizStringField(row, parentField);
350|    if (parentId && nodeMap.has(parentId)) {
351|      nodeMap.get(parentId)!.children.push(node);
352|    } else {
353|      roots.push(node);
354|    }
355|  });
356|  return roots;
